/// <reference types="cypress" />
/**
 * Kite-participant lane-local helpers (T3). NOT steward-owned — single-owner to
 * the `kite` tranche (subsumes the retired range-x-* Playwright specs). Shared
 * foundation (cy.login, cy.origin, personas, selectors, the participant seam
 * commands cy.loginParticipantX / cy.task('seedXParticipant'|'participantLogin'))
 * lives under support/ + tasks/ and is FROZEN — do not edit it.
 *
 * Serving topology (this stack):
 *   - shell-mfe           http://localhost:5173  (Cypress baseUrl; instructor surface)
 *   - kite-mfe standalone http://localhost:5181  (participant "X clone", base "/k/")
 *   - range-bff           http://localhost:8087  (owns /api/v1/kite/* + /api/v1/range/*)
 *
 * kite-mfe's own nginx proxies /api/v1/ to range-bff, so the participant app and
 * its /api/v1/kite/* calls are SAME-ORIGIN and the path-scoped kite_session
 * cookie (Path=/api/v1/kite, Secure, SameSite=Lax) attaches. :5181 and :5173
 * share the `localhost` superdomain, so no cy.origin is needed to drive the
 * participant surface — only Keycloak (:8080) needs cy.origin, which cy.login
 * owns.
 *
 * INSTRUCTOR seeding rides the SHELL ORIGIN (relative /api/v1/range/... paths,
 * baseUrl :5173) through cy.request, riding the current cy.login session cookie
 * — mirrors the range lane. A direct :8087 call carries no bearer and 401s.
 */

/** kite-mfe standalone origin (participant "X clone"). */
export const KITE_MFE_URL =
  (Cypress.env("KITE_MFE_URL") as string | undefined) ?? "http://localhost:5181";

const JSON_HEADERS = {
  "Content-Type": "application/json",
  Accept: "application/json",
} as const;

interface Envelope<T> {
  data?: T;
}

/** Unwrap the range-bff `{ data: ... }` envelope, tolerating a bare payload. */
function unwrap<T>(body: unknown): T {
  if (body && typeof body === "object" && "data" in body) {
    const env = body as Envelope<T>;
    if (env.data !== undefined) return env.data;
  }
  return body as T;
}

// ---------------------------------------------------------------------------
// Navigation (locale-pinned so the m.range_kite_* / m.range_credential_* copy
// the specs assert against renders in en-US — testIsolation clears
// localStorage and the OIDC flow never sets the locale, so seed it on every
// navigation).
// ---------------------------------------------------------------------------

/** Visit a SHELL route (instructor surface) with the Paraglide locale pinned. */
export function visitRange(path: string): void {
  cy.visit(path, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
    },
  });
}

/** Visit a PARTICIPANT (kite-mfe) URL with the Paraglide locale pinned to en-US. */
export function visitKite(path: string): void {
  cy.visit(`${KITE_MFE_URL}${path}`, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
    },
  });
}

/**
 * Compose a post on the participant home feed, robustly.
 *
 * FeedPanel prepends a freshly-composed post OPTIMISTICALLY — but only when
 * `useKiteFeed` has already reached state==="data" (its `onCompose` guards on
 * `feed.state === "data"`). If we type + submit while the initial feed fetch is
 * still in flight, the prepend is a silent no-op and the post never appears
 * client-side (there is no refetch), so a bare `cy.contains("article", body)`
 * would time out even though the write succeeded. A freshly-seeded exercise has
 * an empty feed, so the "No posts yet." empty state renders EXACTLY when the
 * feed reaches state==="data" — waiting on it is the deterministic precondition
 * for the optimistic prepend to fire. Generous timeouts absorb session
 * bootstrap + feed load on a cold shared stack.
 */
export function composeKitePost(body: string): void {
  // Feed reached state==="data" (empty exercise → empty state visible).
  cy.findByText("No posts yet.", { timeout: 30_000 }).should("be.visible");
  cy.findByPlaceholderText("What is happening?", { timeout: 30_000 }).type(body);
  // The only "Post" button on the participant surface is the composer's submit
  // (the left nav exposes Home / Profile / Logout — no Post). `.first()` is
  // defensive against any future duplicate.
  cy.findAllByRole("button", { name: "Post" }).first().click();
}

// ---------------------------------------------------------------------------
// range-bff seeding through the shell proxy (rides the cy.login session cookie)
// ---------------------------------------------------------------------------

/** POST to the range surface through the shell proxy. */
export function bffPost(
  path: string,
  body: object = {},
  failOnStatusCode = true,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "POST",
    url: path,
    body,
    headers: JSON_HEADERS,
    failOnStatusCode,
  });
}

/** GET from the range surface through the shell proxy. */
export function bffGet(
  path: string,
  failOnStatusCode = true,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "GET",
    url: path,
    headers: { Accept: "application/json" },
    failOnStatusCode,
  });
}

/** Create an exercise; yields its id. Creator is auto-enrolled with admin access. */
export function createExercise(name: string): Cypress.Chainable<string> {
  return bffPost("/api/v1/range/exercises", {
    name,
    description: "kite-lane e2e",
  }).then((resp) => {
    const inner = unwrap<{ exercise?: { id?: string }; id?: string }>(resp.body);
    const id = inner.exercise?.id ?? inner.id;
    expect(id, "created exercise id").to.be.a("string");
    return id as string;
  });
}

/** Move an exercise to a status (e.g. "active"). */
export function setExerciseStatus(
  exerciseId: string,
  status: string,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return bffPost(`/api/v1/range/exercises/${exerciseId}/status`, { status });
}

/** Create a published faction; yields its id. */
export function createFaction(
  exerciseId: string,
  name: string,
): Cypress.Chainable<string> {
  return bffPost(`/api/v1/range/exercises/${exerciseId}/factions`, {
    name,
    description: `${name} description`,
    size: "small",
    stance_keywords: ["test"],
  }).then((resp) => {
    const inner = unwrap<{ faction?: { id?: string }; id?: string }>(resp.body);
    const id = inner.faction?.id ?? inner.id;
    expect(id, "created faction id").to.be.a("string");
    return id as string;
  });
}

export interface LoginnableCharacter {
  id: string;
  username: string;
  displayName: string;
}

/**
 * Create a NON-synthetic (human-playable, therefore credentialable) character.
 * AI-only characters (is_synthetic && no owner) can never be credentialed, so
 * the credential affordance only renders for a human-playable profile.
 */
export function createLoginnableCharacter(
  exerciseId: string,
  factionId: string,
  username: string,
  displayName: string,
): Cypress.Chainable<LoginnableCharacter> {
  return bffPost(`/api/v1/range/exercises/${exerciseId}/characters`, {
    faction_id: factionId,
    username,
    display_name: displayName,
    bio: "e2e participant",
    is_synthetic: false,
  }).then((resp) => {
    const inner = unwrap<{
      character?: { id?: string; username?: string; display_name?: string };
    }>(resp.body);
    const id = inner.character?.id;
    expect(id, "created character id").to.be.a("string");
    return {
      id: id as string,
      username: inner.character?.username ?? username,
      displayName: inner.character?.display_name ?? displayName,
    };
  });
}

/** A short unique suffix for parallel-safe seed names. */
export function uniq(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}`;
}


