/**
 * Kite participant security invariants (Epic #262, personas P9 + P6).
 *
 * Three groups:
 *
 *   A. Gate 7 — no self-signup on /k/login. The participant login screen exposes
 *      NO register / sign-up / create-account / self-serve password-reset
 *      affordance. Locale-independent role-name assertions (the i18n-gate audit
 *      already enforces the per-locale text).
 *
 *   B. Structural absence of the instructor surface on the participant standalone
 *      app. The kite-mfe (:5181) serves ONLY the participant /k/* routes — there
 *      is NO credential-management (Generate/Rotate/Revoke), NO instructor "view
 *      as participant" lens, and any non-participant path redirects to /k/login.
 *      The instructor surface lives behind the Keycloak shell, never here.
 *
 *   C. API-level participant-auth invariants (range-bff): a bad login 401s with a
 *      generic, non-enumerating body; a participant session is tenant-scoped
 *      (cannot read a foreign exercise); and an instructor revoke immediately
 *      kills the live session.
 *
 * Subsumes: range-x-security.spec.ts (Group A + Group B API invariants) and the
 * participant-flow revoke assertion.
 */

import { visitKite, KITE_MFE_URL } from "./_helpers";

describe("kite: participant security", () => {
  // ── A. Gate 7 — no self-signup on /k/login ──────────────────────────────
  it("exposes no register / sign-up / create-account / reset affordance on /k/login", () => {
    cy.clearCookies();
    visitKite("/k/login");
    cy.findByRole("heading", { name: "Log in to Range", timeout: 15_000 }).should(
      "be.visible",
    );

    cy.findByRole("link", {
      name: /sign\s*up|register|create\s+account/i,
    }).should("not.exist");
    cy.findByRole("button", {
      name: /sign\s*up|register|create\s+account/i,
    }).should("not.exist");
    cy.findByRole("link", {
      name: /forgot|reset\s+password|recover/i,
    }).should("not.exist");
    cy.findByRole("button", {
      name: /forgot|reset\s+password|recover/i,
    }).should("not.exist");
  });

  // ── B. Instructor surface structurally absent on the participant app ─────
  it("the authenticated participant feed exposes no instructor credential/lens controls", () => {
    cy.loginParticipantX().then(({ exerciseId }) => {
      visitKite(`/k/${exerciseId}/home`);
      cy.findByRole("tab", { name: "For you", timeout: 15_000 }).should(
        "be.visible",
      );

      // No credential-management affordance (Generate / Rotate / Revoke).
      cy.findByRole("button", {
        name: /generate login|rotate password|revoke/i,
      }).should("not.exist");
      // No instructor "view as participant" lens overlay control.
      cy.findByText("View as participant").should("not.exist");
      // No admin navigation off the participant surface.
      cy.findByRole("link", { name: /admin/i }).should("not.exist");
    });
  });

  it("a non-participant path on the standalone app redirects to the login screen", () => {
    cy.clearCookies();
    // An instructor-style path the participant app does not serve.
    visitKite("/k/00000000-0000-0000-0000-0000000000ff/admin/profiles");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/k/login");
    cy.findByRole("heading", { name: "Log in to Range" }).should("be.visible");
  });

  // ── C. API-level participant-auth invariants ────────────────────────────
  it("a bad login 401s with a generic, non-enumerating body and mints no cookie", () => {
    const exerciseId = "00000000-0000-0000-0000-0000000000ff";
    const req = (handle: string, password: string) =>
      cy.request({
        method: "POST",
        url: `${KITE_MFE_URL}/api/v1/kite/login`,
        body: { exercise_id: exerciseId, handle, password },
        headers: { "Content-Type": "application/json" },
        failOnStatusCode: false,
      });

    req("no_such_handle", "x").then((r1) => {
      req("another_missing", "y").then((r2) => {
        // The no-enumeration invariant is what matters: both attempts get the
        // SAME opaque denial with an IDENTICAL body and NO session cookie. The
        // exact denial code is a denial (401 for a bad credential in a real
        // exercise; range-svc may map a nonexistent exercise to 403/404) — the
        // guarantee is that bad-handle and bad-password are indistinguishable.
        expect(r1.status, "identical status — no enumeration").to.eq(r2.status);
        expect([401, 403, 404]).to.include(r1.status);
        // No session minted on a failed login.
        expect(r1.headers["set-cookie"]).to.be.undefined;
        // Bad-handle and bad-password are indistinguishable (no enumeration).
        expect(JSON.stringify(r1.body)).to.eq(JSON.stringify(r2.body));
      });
    });
  });

  it("a participant session is tenant-scoped and cannot read a foreign exercise feed", () => {
    cy.loginParticipantX().then(({ exerciseId }) => {
      // The participant CAN read their own exercise feed.
      cy.request({
        method: "GET",
        url: `${KITE_MFE_URL}/api/v1/kite/exercises/${exerciseId}/feed`,
        failOnStatusCode: false,
      })
        .its("status")
        .should("eq", 200);

      // A DIFFERENT exercise id is invisible under tenant scope: 403 / 404 /
      // 200-with-empty — never another tenant's posts.
      const foreignExerciseId = "00000000-0000-0000-0000-0000000000bb";
      cy.request({
        method: "GET",
        url: `${KITE_MFE_URL}/api/v1/kite/exercises/${foreignExerciseId}/feed`,
        failOnStatusCode: false,
      }).then((r) => {
        expect([403, 404, 200]).to.include(r.status);
        if (r.status === 200) {
          const body = r.body as { posts?: unknown[] };
          expect(body.posts ?? []).to.have.length(0);
        }
      });
    });
  });

  it("an instructor revoke immediately kills the participant session (next /me 401s)", () => {
    // Instructor session first (cy.session clears cookies), THEN plant the
    // participant kite_session so the revoke can be observed to kill it.
    cy.login("P6");
    cy.loginParticipantX().then(({ exerciseId, characterId }) => {
      // The session resolves before revoke.
      cy.request({
        method: "GET",
        url: `${KITE_MFE_URL}/api/v1/kite/me`,
        failOnStatusCode: false,
      })
        .its("status")
        .should("eq", 200);

      // Instructor revokes via the shell surface (rides the P6 session cookie).
      cy.request({
        method: "POST",
        url: `/api/v1/kite/exercises/${exerciseId}/credentials:revoke`,
        body: { character_id: characterId },
        headers: { "Content-Type": "application/json" },
      });

      // The live session is purged — the participant's next /me 401s.
      cy.request({
        method: "GET",
        url: `${KITE_MFE_URL}/api/v1/kite/me`,
        failOnStatusCode: false,
      })
        .its("status")
        .should("eq", 401);
    });
  });
});



