): Cypress.Chainable<LoginnableCharacter> {
  return bffPost(`/api/v1/range/exercises/${exerciseId}/characters`, {
    faction_id: factionId,
    username,
    display_name: displayName,
    bio: "e2e participant",
    is_synthetic: false,
  }).then((resp) => {
    const inner = unwrap<{
      character?: { id?: string; username?: string; display_name?: string };
    }>(resp.body);
    const id = inner.character?.id;
