/**
 * Kite participant login (Epic #262, persona P9).
 *
 * The kite-mfe "X clone" is served OUTSIDE the Keycloak shell; the participant
 * authenticates with a per-character CREDENTIAL, not a Keycloak session. The
 * cy.loginParticipantX seam provisions an exercise + synthetic character +
 * credential, logs the credential in, and plants the kite_session cookie
 * (Path=/api/v1/kite). Because kite-mfe's nginx proxies /api/v1/ to range-bff,
 * the participant app is same-origin with its API and the cookie attaches.
 *
 * Subsumes: range-x-participant-flow.spec.ts (login → feed landing).
 */

import { visitKite } from "./_helpers";

describe("kite: participant login (P9)", () => {
  it("lands on the exercise feed as the credentialed character", () => {
    cy.loginParticipantX().then(({ exerciseId, handle }) => {
      expect(handle, "seam yields the participant handle").to.be.a("string");

      // Arrive directly at the feed with the planted kite_session —
      // AuthedShell bootstraps via GET /api/v1/kite/me (cookie same-origin)
      // and renders.
      visitKite(`/k/${exerciseId}/home`);

      cy.location("pathname", { timeout: 30_000 }).should(
        "eq",
        `/k/${exerciseId}/home`,
      );

      // The feed is ready: the X-style tablist is mounted.
      cy.findByRole("tab", { name: "For you" }).should("be.visible");
      cy.findByRole("tab", { name: "Following" }).should("be.visible");

      // The composer (participant can act as their character).
      cy.findByPlaceholderText("What is happening?").should("be.visible");
    });
  });

  it("an unauthenticated visit to a feed route redirects to the login screen", () => {
    // No cy.loginParticipantX → no kite_session cookie planted.
    cy.clearCookies();
    visitKite("/k/00000000-0000-0000-0000-0000000000ff/home");

    // AuthedShell redirects an unauthenticated participant to /k/login.
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/k/login");
    cy.findByRole("heading", { name: "Log in to Range" }).should("be.visible");
  });
});


